const data = JSON.parse($input.first().json.output);

const salida = [];

// ---------------------------------
// 1. ACCIÓN SOBRE PERFIL
// ---------------------------------
if (data.perfil?.accion === 'actualizar') {
  salida.push({
    json: {
      respuesta: data.respuesta,
      tipo: 'perfil',
      accion: 'actualizar_perfil',
      record_id: data.perfil.record_id ?? null,
      user_name: data.perfil.user_name ?? null
    }
  });
}

// ---------------------------------
// 2. ACCIONES SOBRE MEMORIA
// ---------------------------------
const memoria = data.memoria ?? [];

for (const m of memoria) {
  salida.push({
    json: {
      respuesta: data.respuesta,
      tipo: 'memoria',
      accion: m.accion,
      record_id: m.record_id ?? null,
      id_memoria_largo_plazo: m.id_memoria_largo_plazo ?? null,
      clave: m.clave ?? null,
      valor: m.valor ?? null
    }
  });
}

// ---------------------------------
// 3. SI NO HAY NINGUNA ACCIÓN
// ---------------------------------
if (salida.length === 0) {
  salida.push({
    json: {
      respuesta: data.respuesta,
      tipo: 'sin_accion',
      accion: 'sin_accion'
    }
  });
}

return salida;

const memoria = $input.all()
  .filter(item => {
    const fields = item.json.fields;
    return fields?.clave && fields?.valor;
  })
  .map(item => {
    const fields = item.json.fields;

    return {
      record_id: item.json.id ?? null,
      id_memoria_largo_plazo: fields.id_memoria_largo_plazo ?? null,
      telefono: fields.telefono ?? null,
      clave: fields.clave,
      valor: fields.valor,
      fecha: fields.Fecha ?? fields.fecha ?? null
    };
  });

return [
  {
    json: {
      memoria
    }
  }
];

// Perfil recuperado desde Airtable
const perfilItem = $input.first().json;
const fields = perfilItem.fields ?? {};

// Memoria que ya fue agrupada anteriormente
const memoria = $('Unifica Memoria').first().json.memoria ?? [];

return [
  {
    json: {
      perfil: {
        record_id: perfilItem.id ?? null,
        telefono: fields.telefono ?? null,
        user_name: fields.user_name ?? null,
        status: fields.status ?? null,
        last_summary: fields.last_summary ?? null,
        message_count: fields.message_count ?? 0,
        fecha_actualizacion: fields.fecha_actualizacion ?? fields.Fecha ?? null
      },
      memoria: memoria
    }
  }
];

const item = $input.first().json;
const fields = item.fields ?? {};

const contadorActual = Number(fields.message_count ?? 0);
const nuevoContador = contadorActual + 1;

return [
  {
    json: {
      ...item,
      fields: {
        ...fields,
        message_count: nuevoContador
      },
      nuevo_message_count: nuevoContador,
      perfil_record_id: item.id
    }
  }
];

